-- ══════════════════════════════════════════════════════════════════════════════════════════════════════════════

do $m$
declare
  c_cut constant text[] := array['public.pirate_ship_step(uuid,timestamp with time zone)', 'public.pirate_add(timestamp with time zone)', 'public.pirate_haunt_of(uuid,integer)',
                                 'public.pirate_pressure_write(timestamp with time zone)', 'public.npc_refit_step(uuid,timestamp with time zone)', 'world.pirate_ship_card(uuid)'];
  c_new constant text[] := array['public.pirate_ord_wanted(integer)', 'public.pirate_next_ord()', 'public.pirate_refit_pay(uuid,bigint,timestamp with time zone)',
                                 'public.pirate_reborn(uuid,timestamp with time zone)', 'public.pirate_commission_fleet(integer,uuid,timestamp with time zone)'];
  c_hubs constant text[] := array['PTC', 'MWY', 'TDC', 'FLO', 'DGA'];
  v_t0        timestamptz := clock_timestamp();
  v_now       timestamptz := now();
  hk          record;
  v_z         record;
  v_def       text;
  v_n         int;
  v_m         int;
  v_fn_before text;
  v_pir       uuid;
  v_fleet     uuid;
  v_s         text;
  v_note      text := 'the pirates are dark in this world: the probe built no fleet';
  v_recv      jsonb;
begin
  perform set_config('statement_timeout', '120s', true);
  perform set_config('lock_timeout', '5s', true);

  -- ── 0. GUARD ──
  if to_regclass('public.pirate_hubs') is not null or exists (select 1 from public.ports p where p.code = any (c_hubs))
     or exists (select 1 from public.world_config where key in ('pirate_respawn_minutes', 'pirate_add_minutes', 'pirate_pressure_max')) then
    raise exception '0409 refuses: it has been applied once';
  end if;
  if to_regprocedure('public.pirate_pay(text,bigint,timestamp with time zone,uuid,uuid)') is null or to_regprocedure('voyage.npc_wreck(uuid,uuid,integer)') is null
     or to_regprocedure('public.refit_yard(uuid)') is null or to_regprocedure('public.npc_refit_cost(uuid)') is null or to_regprocedure('public.fleet_hands(uuid,uuid)') is null
     or to_regprocedure('public.fleet_stores(uuid,numeric)') is null or to_regprocedure('public.sea_zone_at(double precision,double precision)') is null
     or to_regprocedure('public.news_update(text,text,text)') is null or to_regclass('public.npc_refit_waits') is null then
    raise exception '0409 refuses: 0322 / 0328 / 0331 / 0339 / 0347 (the wreck, the quay, the stores, the hoard''s payer, the news) are not all in this world';
  end if;
  v_pir := public.pirate_nation();
  if v_pir is null or public.pirate_capital() is null then
    raise exception '0409 refuses: the pirates (0338) have no capital in this world';
  end if;

  -- ── 1. THE PRE-IMAGES ──
  create temp table pre_0409 (fn text primary key, def text, meta text) on commit drop;
  insert into pre_0409
  select f, replace(pg_get_functiondef(f::regprocedure), E'\r', ''),
         (select coalesce(p.proacl::text, '') || ':' || p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, '') || ':' || p.proowner::text
            from pg_proc p where p.oid = f::regprocedure)
    from unnest(c_cut) f;
  select md5(string_agg(p.oid::regprocedure::text || ':' || md5(replace(pg_get_functiondef(p.oid), E'\r', '')) || ':' || coalesce(p.proacl::text, ''), ',' order by p.oid::regprocedure::text))
    into v_fn_before
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname in ('public', 'cmd', 'world', 'voyage') and p.prokind in ('f', 'p') and not exists (select 1 from unnest(c_cut) f where f::regprocedure = p.oid);

  -- ── 2. THE FIVE HARBOURS (a nested block: 0338's harbours part, with these five's data) ──
  declare
    v_ms_h      jsonb := '{}'::jsonb;
    v_t_h       timestamptz := clock_timestamp();
    v_n_h       int;
    v_seeded_h  boolean;
    v_since_h   timestamptz;
    v_xact0_h   bigint;
    v_xact1_h   bigint;
    v_places_h  int;
    v_newrows_h int;
    v_moved_h   int;
    v_hauled_h  int;
    v_asks_h    int;
    v_harb_h    int;
  begin
    select max(a.since) into v_since_h from public.port_allegiance a;   -- the flag clock does not move (0338): no realm's cities changed
    select exists (select 1 from public.port_treasury t where t.seeded_at is not null) into v_seeded_h;
    select coalesce(sum(s.n_tup_ins + s.n_tup_upd + s.n_tup_del), 0) into v_xact0_h
      from pg_stat_xact_user_tables s where s.schemaname = 'public' and s.relname in ('players', 'treasury_flows', 'treasury_daybook', 'ledger');

    -- (1) the harbours (scripts/lib/world-derive.mjs over data/ports.json)
    insert into public.ports (code, name, country, nation_id, lat, lon, sea_id, region_id, culture,
                              size_tier, max_draft, has_yard, yard_tier, has_academy,
                              dev_industry, dev_commerce, dev_military, tax_rate, crew_pool)
    select v.code, v.name, v.country, n.id, v.lat, v.lon, s.id, r.id, v.culture,
           v.size_tier, v.max_draft, v.yard_tier > 0, v.yard_tier, v.academy,
           v.dev_i, v.dev_c, v.dev_m, 0.03, v.crew_pool
      from (values
/*PORTS*/
      ) as v(code, name, country, nation_code, lat, lon, sea_code, region_code, culture, size_tier, max_draft, yard_tier, academy, dev_i, dev_c, dev_m, crew_pool)
      join public.seas s on s.code = v.sea_code
      join public.regions r on r.code = v.region_code
      left join public.nations n on n.code = v.nation_code;
    get diagnostics v_n_h = row_count;
    if v_n_h <> 5 then
      raise exception '0409 (harbours) FAIL: % harbour(s) inserted, 5 expected (a sea, region or nation code is missing)', v_n_h;
    end if;
    create temp table new_h on commit drop as
      select p.id, p.code, p.lat, p.lon, p.size_tier from public.ports p where p.code = any (c_hubs);

    -- (2) the offers and (3) what each makes (0280's rule: raw goods of its own roster). Flores is a NAMED ENTREPOT of salt-cod and virginia-leaf (data/goods.json: the
    --     corsairs' mart for what the returning fleets carried): its region has only two native goods with a free place, and no good is given its FIRST roster maker here
    --     (that would turn a good that is made and not sold into a traded one everywhere).
    update public.goods g set entrepot_ports = array_append(g.entrepot_ports, 'FLO') where g.code in ('salt-cod', 'virginia-leaf') and not ('FLO' = any (g.entrepot_ports));
    get diagnostics v_n_h = row_count;
    if v_n_h <> 2 then
      raise exception '0409 (harbours) FAIL: % good(s) named Flores an entrepot, 2 expected', v_n_h;
    end if;
    insert into public.port_specialties (port_id, good_id)
    select p.id, g.id
      from (values
/*OFFERS*/
      ) as v(port_code, good_code)
      join public.ports p on p.code = v.port_code
      join public.goods g on g.code = v.good_code;
    get diagnostics v_n_h = row_count;
    if v_n_h <> 20 then
      raise exception '0409 (harbours) FAIL: % offer(s) inserted, 20 expected (a good code is missing)', v_n_h;
    end if;
    insert into public.city_production (port_id, good_id, rank)
    select p.id, g.id, v.rank
      from (values
/*PRODUCTION*/
      ) as v(port_code, good_code, rank)
      join public.ports p on p.code = v.port_code
      join public.goods g on g.code = v.good_code;
    get diagnostics v_n_h = row_count;
    if v_n_h <> 9 then
      raise exception '0409 (harbours) FAIL: % production row(s) inserted, 9 expected', v_n_h;
    end if;

    -- (4) the water: each roadstead, its sailed distance to and from every place, its merchant courses (gen-sea.mjs: the game's grid and pathfinder)
    insert into public.sea_reaches (port_id, code, snap_nm, roadstead_lat, roadstead_lon, reaches)
    select p.id, v.code, v.snap_nm::numeric, v.rlat::numeric, v.rlon::numeric, v.reaches::jsonb
      from (values
/*REACHES*/
      ) as v(code, snap_nm, rlat, rlon, reaches)
      join public.ports p on p.code = v.code;
    get diagnostics v_n_h = row_count;
    if v_n_h <> 5 then
      raise exception '0409 (harbours) FAIL: % reach row(s) inserted, 5 expected', v_n_h;
    end if;
    update public.sea_reaches sr
       set reaches = sr.reaches || (select jsonb_object_agg(d.code, (d.reaches ->> sr.code)::numeric) from public.sea_reaches d where d.code = any (c_hubs))
     where sr.code <> all (c_hubs);
    get diagnostics v_places_h = row_count;
    insert into public.npc_courses (from_port, to_port, course, nm)
    select a.id, b.id, v.course::jsonb,
           (select sum((x ->> 'nm')::numeric) from jsonb_array_elements(voyage.segments_from_course(v.course::jsonb)) x)
      from (values
/*COURSES*/
      ) as v(from_code, to_code, course)
      join public.ports a on a.code = v.from_code
      join public.ports b on b.code = v.to_code;
    get diagnostics v_n_h = row_count;
    if v_n_h <> /*NCOURSES*/ then
      raise exception '0409 (harbours) FAIL: % merchant course(s) inserted, /*NCOURSES*/ expected', v_n_h;
    end if;

    -- (5) the market, (6) the buildings, (7.1) the purse at 0 and (7.2) the works: 0338's own lines for a new harbour, verbatim
/*MARKET*/

    -- (7.3) the flag: held by the pirates, NOT a home (a great power's homes are four); since = the flag clock as it stood
    insert into public.port_allegiance (port_id, nation_id, home, since)
    select n.id, v_pir, false, v_since_h from new_h n;
    -- (7.4) the tongue (data/captains.generated.json) and (7.5) the people (data/port-population.json)
    insert into public.port_language (port_id, language)
    select p.id, v.language
      from (values
/*LANGS*/
      ) as v(code, language)
      join public.ports p on p.code = v.code;
    insert into public.port_population (port_id, baseline, year, confidence, note, population)
    select p.id, v.baseline, v.year, v.confidence, v.note, v.baseline
      from (values
/*POP*/
      ) as v(code, baseline, year, confidence, note)
      join public.ports p on p.code = v.code;
    -- (7.6) what the waters ask (0403): every pair that touches a new harbour takes the seas of its plotted course (gen-legs.mjs: the browser's
    --       pathfinder, then public.course_zones; the same rows are in data/sea-legs.json, which the world guard holds this table equal to)
    create temp table legs_h on commit drop as
    select split_part(e, ' ', 1) as f, split_part(e, ' ', 2) as t, string_to_array(substr(e, 9), ' ') as z
      from unnest(string_to_array($legs$/*LEGROWS*/$legs$, '|')) e;
    insert into public.sea_leg_asks (from_port, to_port, wave_min, title_min, zones)
    select a.id, b.id, greatest(q.wave_min, zt.wave_min)::int, greatest(q.title_min, zt.title_min)::int, q.zones
      from legs_h l join public.ports a on a.code = l.f join public.ports b on b.code = l.t
      join public.sea_zones zt on zt.code = public.harbour_zone(b.id)
     cross join lateral (select array_agg(z.code order by z.code) as zones, max(z.wave_min) as wave_min, max(z.title_min) as title_min, count(*) as n
                           from public.sea_zones z where z.code = any (l.z)) q
     where q.n = cardinality(l.z);
    get diagnostics v_asks_h = row_count;
    insert into public.sea_leg_asks (from_port, to_port, wave_min, title_min, zones)
    select n.id, n.id, z.wave_min, z.title_min, array[z.code]
      from new_h n join public.sea_zones z on z.code = public.harbour_zone(n.id);
    get diagnostics v_n_h = row_count;
    v_asks_h := v_asks_h + v_n_h;

    -- ── the harbours' own assert: their rows only ──
    select count(*) into v_harb_h from public.ports p where p.kind = 'HARBOUR';
    if v_asks_h <> 2 * 5 * (v_harb_h - 5) + 20 + 5 then
      raise exception '0409 (harbours) FAIL: % pair row(s) written, % expected (a sea zone of data/sea-legs.json is not in public.sea_zones, or a harbour is missing)', v_asks_h, 2 * 5 * (v_harb_h - 5) + 25;
    end if;
    if exists (select 1 from public.sea_reaches sr where sr.code = any (c_hubs) and (select count(*) from jsonb_object_keys(sr.reaches)) <> (select count(*) from public.sea_reaches) - 1)
       or exists (select 1 from public.sea_reaches sr where sr.code <> all (c_hubs) and (select count(*) from jsonb_object_keys(sr.reaches) k where k = any (c_hubs)) <> 5)
       or exists (select 1 from public.sea_reaches a join public.sea_reaches b on b.code = any (c_hubs) and b.code <> a.code
                   where (a.reaches ->> b.code)::numeric is distinct from (b.reaches ->> a.code)::numeric)
       or exists (select 1 from public.sea_reaches sr join public.ports p on p.id = sr.port_id cross join lateral voyage.water_roadstead(p.lat, p.lon) w
                   where sr.code = any (c_hubs) and (w.lat, w.lon) is distinct from (sr.roadstead_lat, sr.roadstead_lon)) then
      raise exception '0409 (harbours) FAIL: a hub''s row of public.sea_reaches is not whole, not symmetric, or its roadstead is not voyage.water_roadstead''s';
    end if;
    if exists (select 1 from new_h n where (select count(*) from public.port_goods pg where pg.port_id = n.id) <> (select count(*) from public.goods))
       or exists (select 1 from new_h n join public.port_treasury t on t.port_id = n.id where t.ducats <> 0)
       or (select count(*) from public.port_treasury t where t.port_id in (select id from new_h)) <> 5
       or (select count(*) from public.npc_courses c join new_h n on n.id = c.from_port where exists (select 1 from public.npc_courses b where b.from_port = c.to_port and b.to_port = c.from_port)) <> /*NCOURSES*/ / 2 then
      raise exception '0409 (harbours) FAIL: a hub lacks a market row for a good, holds a purse that is not 0, or a course has no way back';
    end if;
    select coalesce(sum(s.n_tup_ins + s.n_tup_upd + s.n_tup_del), 0) into v_xact1_h
      from pg_stat_xact_user_tables s where s.schemaname = 'public' and s.relname in ('players', 'treasury_flows', 'treasury_daybook', 'ledger');
    if v_xact1_h <> v_xact0_h then
      raise exception '0409 (harbours) FAIL: the harbours wrote % row(s) to players / treasury_flows / treasury_daybook / ledger: no money may move here', v_xact1_h - v_xact0_h;
    end if;
    v_recv := jsonb_build_object('places', v_places_h, 'new_rows', v_newrows_h, 'moved_rows', v_moved_h, 'hauled_rows', v_hauled_h, 'pair_rows', v_asks_h);
  end;
